    if (dist[0] + w < dist[1]) dist[1] = dist[0] + w;
    for (int v = 0; v < n; v++)
        cout << (dist[v] >= LINF ? -1 : dist[v]) << ' ';   // -1 = nieosiągalny
    cout << '\n';

    int a[100];
    memset(a, 0x3f, sizeof a);     // każdy int = 0x3f3f3f3f
    cout << a[0] << '\n';          // 1061109567
}

