#include <bits/stdc++.h>
using namespace std;

// a + b dla nieujemnych liczb zapisanych dziesiętnie
string add(const string& a, const string& b) {
    string r;
    int i = a.size() - 1, j = b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        r += char('0' + s % 10);
        carry = s / 10;
    }
    reverse(r.begin(), r.end());
    return r;
}

// a * b dla nieujemnych
string mul(const string& a, const string& b) {
    int n = a.size(), m = b.size();
    vector<int> res(n + m, 0);
    for (int i = n - 1; i >= 0; i--)
        for (int j = m - 1; j >= 0; j--)
            res[i + j + 1] += (a[i] - '0') * (b[j] - '0');
    for (int k = n + m - 1; k > 0; k--) {     // przeniesienia
        res[k - 1] += res[k] / 10;
        res[k] %= 10;
    }
    string r;
    for (int d : res) if (!(r.empty() && d == 0)) r += char('0' + d);
    return r.empty() ? "0" : r;
}

int main() {
    cout << add("99999999999999999999", "1") << '\n';    // 100000000000000000000
    cout << mul("123456789", "987654321") << '\n';       // 121932631112635269
}

// a - b dla a >= b >= 0
string sub(const string& a, const string& b) {
    string r;
    int i = a.size() - 1, j = b.size() - 1, borrow = 0;
    while (i >= 0) {
        int d = (a[i--] - '0') - borrow - (j >= 0 ? b[j--] - '0' : 0);
        borrow = d < 0;
        if (d < 0) d += 10;
        r += char('0' + d);
    }
    while (r.size() > 1 && r.back() == '0') r.pop_back();   // zera wiodące
    reverse(r.begin(), r.end());
    return r;
}

// porównanie nieujemnych bez zer wiodących: -1, 0, 1
int cmp(const string& a, const string& b) {
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    return a < b ? -1 : (a > b ? 1 : 0);
}

